  value=action();observed=await value if hasattr(value,'__await__') else value
 except BaseException as exc:observed=dict(harness_error=type(exc).__name__,detail=str(exc))
 agrees=all(observed.get(k)==v for k,v in expected.items()) if isinstance(expected,dict) and isinstance(observed,dict) else observed==expected
