def concurrent_writers(root):
 s=store(root,'writers');s.save(conv());ready=threading.Barrier(2);results=[]
 def save(label):
  ready.wait(8)
  try:s.save(conv(label));return None
  except sqlite3.Error as exc:return type(exc).__name__
 with ThreadPoolExecutor(max_workers=2) as pool:
  futures=[pool.submit(save,label) for label in ['A','B']]
  results=[f.result(8) for f in futures]
